const DIGITS_TARGET_ENCODED = "";

/** Decode the packed digit pixel string into a flat number array (length 1797*64). */
export function decodeDigitsData(): number[] {
  const s = DIGITS_DATA_ENCODED;
  const n = s.length;
  const out = new Array<number>(n);
  for (let i = 0; i < n; i++) out[i] = s.charCodeAt(i) - 48;
  return out;
}

/** Decode the packed digit target string into a flat class-label array (length 1797). */
export function decodeDigitsTarget(): number[] {
  const s = DIGITS_TARGET_ENCODED;
  const n = s.length;
  const out = new Array<number>(n);
  for (let i = 0; i < n; i++) out[i] = s.charCodeAt(i) - 48;
  return out;
}
